    "lc.bsearch": [["Binary Search", "binary-search", "E"], ["Search a 2D Matrix", "search-a-2d-matrix", "M"], ["Koko Eating Bananas", "koko-eating-bananas", "M"], ["Find Minimum in Rotated Sorted Array", "find-minimum-in-rotated-sorted-array", "M"], ["Search in Rotated Sorted Array", "search-in-rotated-sorted-array", "M"], ["Time Based Key-Value Store", "time-based-key-value-store", "M"], ["Capacity To Ship Packages Within D Days", "capacity-to-ship-packages-within-d-days", "M"], ["Median of Two Sorted Arrays", "median-of-two-sorted-arrays", "H"]],
