    "lc.linked": [["Reverse Linked List", "reverse-linked-list", "E"], ["Merge Two Sorted Lists", "merge-two-sorted-lists", "E"], ["Linked List Cycle", "linked-list-cycle", "E"], ["Middle of the Linked List", "middle-of-the-linked-list", "E"], ["Reorder List", "reorder-list", "M"], ["Remove Nth Node From End of List", "remove-nth-node-from-end-of-list", "M"], ["Copy List with Random Pointer", "copy-list-with-random-pointer", "M"], ["Add Two Numbers", "add-two-numbers", "M"], ["Find the Duplicate Number", "find-the-duplicate-number", "M"], ["LRU Cache", "lru-cache", "M"], ["Reverse Nodes in k-Group", "reverse-nodes-in-k-group", "H"]],
