    "lc.graphadv": [["Course Schedule", "course-schedule", "M"], ["Course Schedule II", "course-schedule-ii", "M"], ["Redundant Connection", "redundant-connection", "M"], ["Number of Connected Components in an Undirected Graph", "number-of-connected-components-in-an-undirected-graph", "M", 1], ["Graph Valid Tree", "graph-valid-tree", "M", 1], ["Network Delay Time", "network-delay-time", "M"], ["Cheapest Flights Within K Stops", "cheapest-flights-within-k-stops", "M"], ["Min Cost to Connect All Points", "min-cost-to-connect-all-points", "M"], ["Swim in Rising Water", "swim-in-rising-water", "H"], ["Alien Dictionary", "alien-dictionary", "H", 1], ["Reconstruct Itinerary", "reconstruct-itinerary", "H"]],
